<template><q-card flat bordered class="users-card"><q-card-section><div class="section-title"><q-icon name="groups"/> Usuarios</div><q-input v-model="busqueda" outlined dense clearable label="Buscar usuario o rol"><template #prepend><q-icon name="search"/></template></q-input></q-card-section><q-separator/><q-list separator><q-item v-for="usuario in filtrados" :key="usuario.id" clickable :active="usuario.id===seleccionado" active-class="user-active" @click="$emit('seleccionar',usuario.id)"><q-item-section avatar><q-avatar :color="usuario.estado?'green-1':'grey-3'" :text-color="usuario.estado?'green-9':'grey-7'" :icon="usuario.avatar"/></q-item-section><q-item-section><q-item-label class="user-name">{{usuario.nombre}}</q-item-label><q-item-label caption>{{usuario.rol}}</q-item-label><q-item-label caption>Último acceso: {{usuario.ultimoAcceso||'Sin registro'}}</q-item-label></q-item-section><q-item-section side><q-badge :color="usuario.estado?'positive':'grey-6'" :label="usuario.estado?'Activo':'Inactivo'"/><q-btn flat dense no-caps color="green-8" icon="admin_panel_settings" label="Configurar permisos" class="config-btn" @click.stop="$emit('seleccionar',usuario.id)"/></q-item-section></q-item><div v-if="!filtrados.length" class="empty-users">No se encontraron usuarios.</div></q-list></q-card></template>
<script setup>import{computed,ref}from'vue';const props=defineProps({usuarios:{type:Array,required:true},seleccionado:Number});defineEmits(['seleccionar','configurar']);const busqueda=ref('');const filtrados=computed(()=>{const q=busqueda.value.toLowerCase().trim();return props.usuarios.filter(u=>!q||`${u.nombre} ${u.rol}`.toLowerCase().includes(q))})</script>
<style scoped>.users-card{border-radius:16px;height:100%}.section-title{display:flex;align-items:center;gap:8px;margin-bottom:16px;color:#1b5e20;font-size:17px;font-weight:900}.user-name{color:#26352c;font-weight:800}.user-active{background:#edf8ef;border-right:3px solid #2e7d32}.config-btn{font-size:10px;margin-top:6px}.empty-users{padding:25px;text-align:center;color:#87958d}</style>
